CREATE TABLE IF NOT EXISTS leads (id SERIAL PRIMARY KEY, lead_name TEXT NOT NULL, company TEXT, contact_person TEXT, phone TEXT, email TEXT, source TEXT, status TEXT DEFAULT 'New', assigned_user INTEGER REFERENCES users(id) ON DELETE SET NULL, notes TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS deals (id SERIAL PRIMARY KEY, deal_number TEXT UNIQUE, buyer_id BIGINT REFERENCES buyers(id) ON DELETE SET NULL, supplier_id BIGINT REFERENCES suppliers(id) ON DELETE SET NULL, enquiry_id INTEGER REFERENCES enquiries(id) ON DELETE SET NULL, amount NUMERIC DEFAULT 0, stage TEXT DEFAULT 'Qualification', probability INTEGER DEFAULT 0, expected_close_date DATE, status TEXT DEFAULT 'Open', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS quotations (id SERIAL PRIMARY KEY, quote_number TEXT UNIQUE, enquiry_id INTEGER REFERENCES enquiries(id) ON DELETE SET NULL, buyer_id BIGINT REFERENCES buyers(id) ON DELETE SET NULL, supplier_id BIGINT REFERENCES suppliers(id) ON DELETE SET NULL, logistics_lane_id BIGINT REFERENCES logistics_lanes(id) ON DELETE SET NULL, predicted_freight_per_kg NUMERIC(14,4), price NUMERIC, quantity NUMERIC, tax NUMERIC DEFAULT 0, currency TEXT DEFAULT 'INR', valid_till DATE, status TEXT DEFAULT 'Draft', created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS finance (id SERIAL PRIMARY KEY, reference_no TEXT UNIQUE, buyer_id BIGINT REFERENCES buyers(id) ON DELETE SET NULL, supplier_id BIGINT REFERENCES suppliers(id) ON DELETE SET NULL, logistics_cost_id BIGINT REFERENCES logistics_cost_register(id) ON DELETE SET NULL, freight_per_kg NUMERIC(14,4), amount NUMERIC NOT NULL, type TEXT NOT NULL, due_date DATE, payment_status TEXT DEFAULT 'Pending', remarks TEXT, created_at TIMESTAMPTZ DEFAULT now());
ALTER TABLE chemicals ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT now();
ALTER TABLE followups ADD COLUMN IF NOT EXISTS next_followup_date DATE;
ALTER TABLE followups ADD COLUMN IF NOT EXISTS user_id INTEGER REFERENCES users(id) ON DELETE SET NULL;
ALTER TABLE roles ALTER COLUMN permissions SET DEFAULT '{}';
